let mouse = { x: 0, y: 0 }, pos = { x: 0, y: 0 };
function animate() {
  pos.x += (mouse.x - pos.x) * 0.15;
  pos.y += (mouse.y - pos.y) * 0.15;
  cursor.style.transform = `translate3d(${pos.x}px, ${pos.y}px, 0)`;
  requestAnimationFrame(animate);
}

